/**
 * Meet the Team group photos (TH-65). GENERATED by `npm run team:photos`; do not hand-edit.
 * Empty until the script has run with GEMINI_API_KEY; the home page then shows
 * "Group photos coming soon". Alt text and captions use ThoughtForge names only (TF-DEC-13).
 */
export type TeamPhoto = {
  id: string;
  file: string; // 1600 px wide, lightbox source
  fileSm: string; // 800 px wide, grid source
  kind: "formal" | "candid";
  title: string;
  alt: string;
  caption: string;
  generatedAt: string;
  model: string;
};

export const teamPhotos: TeamPhoto[] = [];
